INSERT INTO `projects` VALUES (1,'Nimbe Food','nimbe-food','Nimbe Food','produits alimentaires ',2012,'Nimba Foods est une marque fictive spécialisée dans la transformation et la distribution de produits alimentaires locaux. Elle valorise les ressources du terroir à travers des produits de qualité, alliant authenticité, savoir-faire local et standards modernes.','<p>Bien que disposant de produits de qualité et d’un positionnement clair autour du local, Nimba Foods ne disposait pas encore des fondations nécessaires pour affirmer sa présence sur le marché.</p><p>La marque faisait face à plusieurs enjeux :</p><ul><li><p>L’absence d’une identité visuelle forte et cohérente</p></li><li><p>Un manque de visibilité digitale</p></li><li><p> Des supports de communication limités pour présenter les produits</p></li><li><p> La nécessité d’inspirer confiance et professionnalisme auprès des partenaires et distributeurs</p></li></ul><p>L’objectif était donc de construire une image de marque solide et un écosystème digital capable de soutenir le développement et la croissance de Nimba Foods.</p>','<p>Face à ces enjeux, Welya Creative a accompagné Nimba Foods dans la conception d’une solution digitale complète, pensée pour poser des bases solides et durables.</p><p>Notre mission a consisté à :</p><ul><li><p> Définir une identité de marque claire et cohérente, en phase avec les valeurs du local</p></li><li><p> Concevoir une image moderne et professionnelle capable de renforcer la crédibilité de la marque</p></li><li><p>Créer une présence digitale structurée, facilitant la présentation des produits</p></li><li><p> Mettre en place une expérience utilisateur fluide et intuitive</p></li></ul><p>L’objectif était de transformer Nimba Foods en une marque crédible, identifiable et prête à se développer sur son marché.</p>','<p>Pour répondre aux enjeux de Nimba Foods, Welya Creative a déployé une approche globale, alliant stratégie, design et digital.</p><h4><strong> Branding &amp; identité visuelle</strong></h4><p>Création d’une identité de marque forte incluant logo, palette de couleurs, typographies et ligne graphique, reflétant l’authenticité des produits locaux.</p><h4><strong> Site vitrine professionnel</strong></h4><p>Conception d’un site web moderne et responsive, pensé pour présenter la marque et ses produits de manière claire et structurée.</p><p><strong> Mise en valeur des produits</strong></p><p>Structuration des contenus et création de visuels attractifs pour faciliter la compréhension de l’offre et renforcer l’impact commercial.</p><h4><strong>UX/UI Design</strong></h4><p>Mise en place d’une expérience utilisateur fluide, avec une navigation intuitive et une hiérarchisation claire de l’information.</p><h4><strong>Base pour la croissance digitale</strong></h4><p>Définition d’un socle digital évolutif, prêt à accueillir de futures actions marketing et commerciales.</p>','<p>Ce projet a permis à Nimba Foods de disposer de fondations solides pour son développement :</p><ul><li><p> Une image de marque professionnelle et cohérente, alignée avec ses valeurs</p></li><li><p> Une présence digitale crédible, facilitant la présentation de la marque et de ses produits</p></li><li><p>Des supports clairs pour communiquer efficacement auprès des partenaires et distributeurs</p></li><li><p>Une base digitale évolutive, prête à accompagner la croissance future de la marque</p></li></ul><p>Grâce à cette collaboration, Nimba Foods bénéficie désormais d’un positionnement clair et d’outils adaptés pour renforcer sa visibilité et sa crédibilité sur son marché.</p>','01KD97R6WMM30VJKXP28XYR8BC.jpg',1,'published','2025-12-16 22:15:45','2025-12-28 13:17:27'),(2,'Nostrum distinctio ','nostrum-distinctio','Exercitationem magni','Qui consectetur quo ',1990,'Molestias rerum dolo','<p>Est blanditiis beata</p>','<p>Eiusmod assumenda al</p>','<p>Qui cillum esse ut</p>','<p>Est eos nihil conse</p>','01KDJDTZ360NFSRTRVJ0VW5YAW.jpg',1,'published','2025-12-16 22:16:03','2025-12-28 12:10:47'),(3,'Quis iste q','quis-iste-q','Numquam ulla','m amet vitae qui voluptate ',2025,'Et lorem qui asperio','<p>Adipisicing sed vel</p>','<p>Rem commodo quisquam</p>','<p>Est est odit ea sed</p>','<p>Demo text</p>','01KDJHJYZWJY7G6Q980VV3DEF8.jpg',1,'published','2025-12-16 23:38:40','2025-12-28 13:15:27');
/*!40000 ALTER TABLE `projects` ENABLE KEYS */;
